SELECT jsonb_build_object('name',r.name,'round',r.round,'season',r.id_season,'first',extract(epoch FROM r.event_date)::bigint,'second',extract(epoch FROM r.event2_date)::bigint,'points',p.points,'minimumPoints',p.minimum_points,'bestOf',p.best_of) AS value FROM public.zsl_round r JOIN public.zsl_season s ON s.id=r.id_season JOIN public.zsl_points_structure p ON p.id=s.id_points_structure WHERE r.id=$1
